mapper.update:
UPDATE dodo_restock_supply SET state = #{record.state}, owner_id = #{record.ownerId},
owner_name = #{record.ownerName}, reason = #{record.reason}, expected_at = #{record.expectedAt,jdbcType=TIMESTAMP},
